#!/usr/bin/env python3
"""Build the shipment summary described in /app/docs/summary-format.md."""
import gzip
import json
import os
import re
import sys
import xml.etree.ElementTree as ET
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal, ROUND_HALF_UP, getcontext

getcontext().prec = 60

KG = {
    "kg": Decimal(1),
    "g": Decimal("0.001"),
    "lb": Decimal("0.45359237"),
    "oz": Decimal("0.028349523125"),
}
PRIORITY = ["central", "south", "east", "river", "north", "west", "harbor", "lakeside"]
MONTHS = {m: i + 1 for i, m in enumerate(
    ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"])}

COLUMNS = {
    "east": ["id", "type", "shipped", "gross", "net", "status", "note"],
    "harbor": ["rec", "ref", "date", "weight", "state"],
    "lakeside": ["id", "kind", "booked", "shipped", "gross_kg", "net_kg", "status"],
    "river": ["t", "ref", "shipped", "weight", "status"],
    "west": ["id", "typ", "shipped", "weight", "status", "note"],
}
SEPS = {"east": ",", "lakeside": ",", "harbor": "|", "river": "\t", "west": ";"}
BASE_DATE = {"east": "YMD", "lakeside": "iso", "harbor": "iso",
             "river": "MM/DD/YYYY", "west": "DD.MM.YYYY"}
TYPE_MAP = {"n": "new", "new": "new", "": "new", "c": "correction", "cor": "correction",
            "corr": "correction", "correction": "correction", "amend": "correction",
            "v": "void", "void": "void"}
HARBOR_STATE = {"dlv": "delivered", "dll": "delivered_late", "can": "cancelled",
                "ret": "returned", "hld": "held"}
FW_STATUS = {"D": "delivered", "L": "delivered_late", "C": "cancelled",
             "R": "returned", "H": "held"}


# ---------------------------------------------------------------- bytes/text
def read_text(path):
    with open(path, "rb") as f:
        b = f.read()
    if b[:2] == b"\x1f\x8b":
        b = gzip.decompress(b)
    if b[:3] == b"\xef\xbb\xbf":
        return b[3:].decode("utf-8", "replace")
    if b[:2] in (b"\xff\xfe", b"\xfe\xff"):
        return b.decode("utf-16", "replace")
    enc = "utf-8"
    head = b[:2048].decode("latin-1").split("\n")[:20]
    for line in head:
        m = re.match(r"#\s*charset\s*:\s*(\S+)", line)
        if m:
            enc = m.group(1)
            break
    try:
        return b.decode(enc)
    except (LookupError, UnicodeDecodeError):
        return b.decode("utf-8", "replace")


# ------------------------------------------------------------------- values
def norm_id(s):
    m = re.match(r"\s*SH\D*?(\d+)\s*$", s or "", re.I)
    return int(m.group(1)) if m else None


def norm_status(s):
    return re.sub(r"[\s\-]+", "_", (s or "").strip().lower())


def parse_date(s, form):
    """Return (date, datetime-in-UTC or None) -> a date in UTC."""
    s = (s or "").strip()
    if not s:
        return None
    if "T" in s or re.match(r"\d{4}-\d\d-\d\d[ ]\d", s):
        t = s.replace(" ", "T", 1)
        if t.endswith(("Z", "z")):
            t = t[:-1] + "+00:00"
        dt = datetime.fromisoformat(t)
        if dt.tzinfo is not None:
            dt = dt.astimezone(timezone.utc)
        return dt.date()
    m = re.match(r"(\d{1,2})\s+([A-Za-z]{3})[a-z]*\.?,?\s+(\d{4})$", s)
    if m:
        return date(int(m.group(3)), MONTHS[m.group(2).lower()], int(m.group(1)))
    f = (form or "").strip()
    fl = f.lower()
    if fl == "serial" or (not re.search(r"\D", s.replace(".", "", 1)) and fl == "serial"):
        return date(1899, 12, 30) + timedelta(days=int(float(s)))
    parts = [int(p) for p in re.split(r"[-/.]", s)]
    if len(parts) != 3:
        if fl == "serial" or len(parts) == 1:
            return date(1899, 12, 30) + timedelta(days=int(float(s)))
        raise ValueError(s)
    if len(re.split(r"[-/.]", s)[0]) == 4:
        return date(parts[0], parts[1], parts[2])
    if fl in ("dmy", "dd/mm/yyyy", "dd.mm.yyyy", "dd-mm-yyyy"):
        return date(parts[2], parts[1], parts[0])
    if fl in ("mm/dd/yyyy", "mdy"):
        return date(parts[2], parts[0], parts[1])
    if fl in ("ymd", "iso", "yyyy-mm-dd"):
        return date(parts[0], parts[1], parts[2])
    # unknown form: day-first unless impossible
    return date(parts[2], parts[1], parts[0])


def parse_number(s, depot):
    s = s.strip()
    if depot == "west":
        s = s.replace(".", "").replace(",", ".")
    else:
        s = s.replace(",", "")
    return Decimal(s)


UNIT_RE = re.compile(r"^\s*([-+0-9.,]+)\s*(kg|g|lb|oz)\s*$", re.I)


def unit_of(s):
    m = re.match(r"\s*(kg|g|lb|oz)\b", s or "", re.I)
    return m.group(1).lower() if m else None


# ------------------------------------------------------------ delimited text
def csv_rows(text):
    """Yield ('comment', line) or ('row', [fields]); quotes follow CSV rules."""
    i, n = 0, len(text)
    while i < n:
        c = text[i]
        if c == "\n":
            i += 1
            continue
        if c == "\r" and text[i + 1:i + 2] in ("\n", ""):
            i += 1
            continue
        if c == "#":
            j = text.find("\n", i)
            j = n if j < 0 else j
            yield "comment", text[i:j].rstrip("\r")
            i = j + 1
            continue
        fields, cur = [], []
        while True:
            if i < n and text[i] == '"' and not cur:
                i += 1
                while i < n:
                    if text[i] == '"':
                        if text[i + 1:i + 2] == '"':
                            cur.append('"')
                            i += 2
                            continue
                        i += 1
                        break
                    cur.append(text[i])
                    i += 1
                # junk after closing quote is kept
                while i < n and text[i] not in ",\n":
                    cur.append(text[i])
                    i += 1
            else:
                while i < n and text[i] not in ",\n":
                    cur.append(text[i])
                    i += 1
            if i < n and text[i] == ",":
                fields.append("".join(cur))
                cur = []
                i += 1
                continue
            val = "".join(cur)
            if val.endswith("\r"):
                val = val[:-1]
            fields.append(val)
            i += 1
            break
        yield "row", fields


def plain_rows(text, sep):
    for line in text.split("\n"):
        line = line.rstrip("\r")
        if not line.strip():
            continue
        if line.startswith("#"):
            yield "comment", line
        else:
            yield "row", line.split(sep)


def parse_delimited(depot, text):
    sep = SEPS[depot]
    cols = set(COLUMNS[depot])
    gen = csv_rows(text) if sep == "," else plain_rows(text, sep)
    seq = None
    dirs = {}
    header = None
    out = []
    for kind, val in gen:
        if kind == "comment":
            m = re.match(r"#\s*([^:=]+?)\s*:\s*(.*?)\s*$", val)
            if m:
                name = m.group(1).lower()
                dirs[name] = m.group(2)
                if name == "seq" and seq is None:
                    try:
                        seq = int(m.group(2))
                    except ValueError:
                        pass
            else:
                m = re.search(r"\bseq\s*=\s*(\d+)", val)
                if m and seq is None:
                    seq = int(m.group(1))
            continue
        fields = val
        stripped = [f.strip() for f in fields]
        if stripped and all(f.lower() in cols for f in stripped):
            header = [f.lower() for f in stripped]
            continue
        if header is None:
            header = list(COLUMNS[depot])
        row_unit = None
        if len(fields) == len(header) + 1:
            wcol = next((c for c in ("gross", "weight", "gross_kg") if c in header), None)
            if wcol is not None:
                k = header.index(wcol) + 1
                if k < len(fields) and fields[k].strip().lower() in KG:
                    row_unit = fields[k].strip().lower()
                    fields = fields[:k] + fields[k + 1:]
        if len(fields) < len(header):
            fields = fields + [""] * (len(header) - len(fields))
        r = dict(zip(header, fields))
        rec = build_delimited(depot, r, dirs, row_unit)
        if rec is not None:
            out.append(rec)
    return seq, out


def build_delimited(depot, r, dirs, row_unit):
    ref = r.get("id") or r.get("ref") or ""
    num = norm_id(ref)
    if num is None:
        return None  # trailer or junk
    typ = TYPE_MAP.get((r.get("type") or r.get("rec") or r.get("kind")
                        or r.get("t") or r.get("typ") or "").strip().lower(), "new")
    if typ == "void":
        return {"num": num, "type": "void"}
    wcell = r.get("gross") if "gross" in r else r.get("gross_kg", r.get("weight", ""))
    unit = None
    m = UNIT_RE.match(wcell or "")
    if m:
        wcell, unit = m.group(1), m.group(2).lower()
    if unit is None and "gross_kg" in r and "gross" not in r:
        unit = "kg"
    if unit is None:
        unit = row_unit
    if unit is None:
        for k in ("unit", "weight unit"):
            if k in dirs and unit_of(dirs[k]):
                unit = unit_of(dirs[k])
                break
    if unit is None:
        unit = "kg"
    kg = parse_number(wcell, depot) * KG[unit]
    dform = dirs.get("dates") or dirs.get("date format") or dirs.get("date") \
        or BASE_DATE[depot]
    shipped = r.get("shipped") if "shipped" in r else r.get("date")
    d = parse_date(shipped, dform)
    st = r.get("status") if "status" in r else r.get("state", "")
    st = norm_status(st)
    st = HARBOR_STATE.get(st, st)
    return {"num": num, "type": typ, "kg": kg, "date": d, "status": st}


# ----------------------------------------------------------------- fixed width
FW = {
    41: ("FW3", {"id": (0, 9), "shipped": (9, 16), "type": (16, 17), "weight": (17, 24),
                 "status": (24, 25)}),
    42: ("FW1", {"id": (0, 9), "type": (9, 10), "shipped": (10, 17), "weight": (17, 25),
                 "status": (25, 26)}),
    43: ("FW2", {"type": (0, 1), "id": (1, 10), "shipped": (10, 18), "weight": (18, 26),
                 "status": (26, 27)}),
}
LAYOUT_LEN = {"FW3": 41, "FW1": 42, "FW2": 43}


def parse_fixed(text):
    seq = None
    layout = None
    out = []
    for line in text.split("\n"):
        line = line.rstrip("\r")
        if "\x0c" in line or "SOUTH DEPOT" in line:
            continue
        if not line.strip():
            continue
        if line.startswith("#"):
            m = re.match(r"#LAYOUT\s+(\S+)", line)
            if m:
                layout = m.group(1).upper()
            m = re.match(r"#SEQ\s+(\d+)", line)
            if m and seq is None:
                seq = int(m.group(1))
            continue
        L = len(line)
        if L in FW:
            name, f = FW[L]
        else:
            name = layout
            if name not in LAYOUT_LEN:
                continue
            f = FW[LAYOUT_LEN[name]][1]
            line = line.ljust(LAYOUT_LEN[name])
        g = {k: line[a:b] for k, (a, b) in f.items()}
        num = norm_id(g["id"])
        if num is None:
            continue
        typ = TYPE_MAP.get(g["type"].strip().lower(), "new")
        if typ == "void":
            out.append({"num": num, "type": "void"})
            continue
        w = Decimal(int(g["weight"]))
        if name == "FW1":
            kg = w * KG["g"]
        elif name == "FW2":
            kg = w / 100
        else:
            kg = w / 10 * KG["lb"]
        s = g["shipped"]
        if name == "FW2":
            d = date(int(s[:4]), int(s[4:6]), int(s[6:8]))
        else:
            d = date(int(s[:4]), 1, 1) + timedelta(days=int(s[4:7]) - 1)
        out.append({"num": num, "type": typ, "kg": kg, "date": d,
                    "status": norm_status(FW_STATUS.get(g["status"].strip().upper(), g["status"]))})
    return seq, out


# ------------------------------------------------------------------------ XML
def parse_xml(text):
    text = re.sub(r"^\s*<\?xml[^>]*\?>", "", text.lstrip("﻿"))
    root = ET.fromstring(text.encode("utf-8"))
    try:
        seq = int(root.get("seq"))
    except (TypeError, ValueError):
        seq = None
    runit = (root.get("weight-unit") or "kg").strip().lower()
    out = []
    for el in root.iter("shipment"):
        num = norm_id(el.get("id"))
        if num is None:
            continue
        typ = TYPE_MAP.get((el.get("type") or "").strip().lower(), "new")
        if typ == "void":
            out.append({"num": num, "type": "void"})
            continue
        w = el.find("weight")
        unit = (w.get("unit") or runit).strip().lower() if w is not None else runit
        kg = Decimal(w.text.strip().replace(",", "")) * KG[unit]
        sh = el.get("shipped")
        c = el.find("shipped")
        if c is not None and c.text and c.text.strip():
            sh = c.text
        d = parse_date(sh, None)
        st = el.findtext("status") or el.get("status") or ""
        out.append({"num": num, "type": typ, "kg": kg, "date": d, "status": norm_status(st)})
    return seq, out


# ----------------------------------------------------------------- JSON lines
def parse_jsonl(text):
    seq = None
    out = []
    for line in text.split("\n"):
        line = line.strip()
        if not line:
            continue
        v = json.loads(line)
        for o in (v if isinstance(v, list) else [v]):
            if not isinstance(o, dict):
                continue
            if "meta" in o and "id" not in o:
                if seq is None:
                    try:
                        seq = int(o["meta"].get("seq"))
                    except (TypeError, ValueError, AttributeError):
                        pass
                continue
            num = norm_id(str(o.get("id", "")))
            if num is None:
                continue
            typ = TYPE_MAP.get(str(o.get("kind") or "new").strip().lower(), "new")
            if typ == "void":
                out.append({"num": num, "type": "void"})
                continue
            kg = None
            for k, val in o.items():
                m = re.match(r"weight_(kg|g|lb|oz)$", k, re.I)
                if m:
                    kg = Decimal(str(val)) * KG[m.group(1).lower()]
                    break
            if kg is None and "weight" in o:
                kg = Decimal(str(o["weight"])) * KG[str(o.get("unit", "kg")).lower()]
            out.append({"num": num, "type": typ, "kg": kg,
                        "date": parse_date(o.get("shipped_at"), None),
                        "status": norm_status(o.get("status"))})
    return seq, out


# ----------------------------------------------------------------------- main
def parse_file(depot, path):
    text = read_text(path)
    if text.startswith("﻿"):
        text = text[1:]
    head = text.lstrip()[:1]
    if depot in SEPS:
        return parse_delimited(depot, text)
    if head == "<":
        return parse_xml(text)
    if head in "{[":
        return parse_jsonl(text)
    return parse_fixed(text)


def main():
    data_dir, out_file = sys.argv[1], sys.argv[2]
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, name)
        if not os.path.isfile(p):
            continue
        depot = name.split("-", 1)[0]
        seq, recs = parse_file(depot, p)
        exports.setdefault(depot, []).append((seq if seq is not None else 0, name, recs))

    corrections = resends = 0
    current = {}
    for depot, exps in exports.items():
        cur = {}
        for _, _, recs in sorted(exps, key=lambda e: (e[0], e[1])):
            for r in recs:
                n = r["num"]
                if r["type"] == "new":
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r["type"] == "correction":
                    corrections += 1
                    cur[n] = r
                else:
                    corrections += 1
                    cur.pop(n, None)
        current[depot] = cur

    order = {d: i for i, d in enumerate(PRIORITY)}
    by_num = {}
    for depot, cur in current.items():
        for n, r in cur.items():
            by_num.setdefault(n, []).append((order.get(depot, len(order)), depot, r))
    handovers = 0
    depots = {d: [0, Decimal(0)] for d in exports}
    months = {}
    for n, lst in by_num.items():
        if len(lst) > 1:
            handovers += 1
        _, depot, r = min(lst, key=lambda x: (x[0], x[1]))
        if r["status"] not in ("delivered", "delivered_late"):
            continue
        depots[depot][0] += 1
        depots[depot][1] += r["kg"]
        key = "%04d-%02d" % (r["date"].year, r["date"].month)
        m = months.setdefault(key, [0, Decimal(0)])
        m[0] += 1
        m[1] += r["kg"]

    def fmt(v):
        return float(v.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))

    result = {
        "depots": {d: {"shipments": v[0], "total_kg": fmt(v[1])}
                   for d, v in sorted(depots.items())},
        "months": {k: {"shipments": v[0], "total_kg": fmt(v[1])}
                   for k, v in sorted(months.items())},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w") as f:
        json.dump(result, f, indent=2)
        f.write("\n")


if __name__ == "__main__":
    main()

